insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('ff53f472-c8b8-45e6-a67e-d63463c87433', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', $$inleiding: minigifklieren van Clevers gekweekt in het lab$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-context1.png$$,
   $$Wereldwijd sterven jaarlijks ruim 100.000 mensen door beten van giftige slangen. Het team van Hans Clevers van het Hubrecht Instituut in Utrecht is erin geslaagd om minigifklieren te kweken in het laboratorium. Hierdoor kan het eenvoudiger worden om antiserum tegen slangengif te produceren.$$, 'inline'),
  ('d0c0b48d-a9c6-430a-a60f-a9ef5149d3cf', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', $$gifklier met afvoerbuisje en drie celtypen (afbeelding 1)$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-context2.png$$,
   $$Gifklieren van slangen zijn aangepaste speekselklieren. Slangengif bevat een mix van verschillende eiwitten die een prooi kunnen verlammen en verteren. Als een slang bijt, trekt de compressie-spier rond de gifklier samen, waardoor het gif via een afvoerbuisje door de giftand (afbeelding 1) in de prooi terechtkomt.
afbeelding 1
De gifklier met afvoerbuisje bestaat uit drie typen cellen: epitheelcellen, mitochondria-rijke zuurproducerende cellen en gifproducerende cellen.$$, 'inline'),
  ('f4fbb737-b8ae-4ac4-b841-cc1e8a9ae5b3', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', $$drie uitspraken over de gifklier en het afvoerbuisje$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-context3.png$$,
   $$Hieronder staan uitspraken over de gifklier en het afvoerbuisje.
1 De gifklier is een exocriene klier.
2 De mitochondria-rijke cellen produceren ATP voor de cellen van de compressie-spier.
3 De binnenkant van het afvoerbuisje bestaat voornamelijk uit epitheelcellen.$$, 'inline'),
  ('03340a5f-a863-467b-8f03-31ef10895e8e', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', $$gifproducerende cellen met veel ribosomen en golgi-systeem$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-context4.png$$,
   $$De gifproducerende cellen bevatten een groot aantal ribosomen en een groot golgi-systeem.$$, 'inline'),
  ('20c11195-2fa0-451e-bd78-6cc27b8337bd', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', $$productie van antiserum door melken en injecteren van gif (afbeelding 2)$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-context5.png$$,
   $$Na een beet van een giftige slang is het afbeelding 2 heel belangrijk dat een antiserum wordt toegediend. Voor het maken van zo’n antiserum worden slangen gemolken (afbeelding 2). Het verkregen gif wordt sterk verdund en vervolgens ingespoten bij ‘productiedieren’, bijvoorbeeld paarden of schapen. Bij die dieren komt dan een immuunreactie op gang, waarna de antistoffen uit het bloedplasma geïsoleerd kunnen worden.$$, 'inline'),
  ('fbf4145b-264f-4d6b-b2d8-24f17c75427c', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', $$specifiek antiserum nodig per slangensoort$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-context6.png$$,
   $$Tegen het gif van elke slangensoort moet een specifiek antiserum geproduceerd worden.$$, 'inline'),
  ('f4c98945-8cd1-4bb3-9e8b-55e43dfcc363', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', $$kweken van minigifkliertjes tot organoïden (afbeelding 3, afbeelding 4)$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-context7.png$$,
   $$De Utrechtse onderzoekers gebruikten voor het kweken van de minigifkliertjes de gifklieren van negen verschillende soorten slangen. De onderzoekers maakten cellen los uit het weefsel van de gifklier en brachten deze in een voedingsmedium met groeifactoren. Bepaalde cellen gingen zich delen en vormden spontaan bolletjes (afbeelding 3). Na een week begonnen de cellen van elk bolletje zich te differentiëren tot verschillende celtypen, waaronder gifproducerende cellen. De bolletjes ontwikkelden zich tot blaasjes die organoïden genoemd worden (doorsnede in afbeelding 4).
afbeelding 3 afbeelding 4$$, 'inline'),
  ('2068a2e9-518a-437d-b33d-a30d857a98f7', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', $$eerste keer organoïden gekweekt uit stamcellen van reptielen$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-context8.png$$,
   $$Dit was de eerste keer dat het wetenschappers lukte om organoïden te kweken uit stamcellen van reptielen.$$, 'inline'),
  ('a5ba4d7d-138b-417a-abbe-4c72694d277e', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', $$vergelijking van mRNA van organoïden met gifklier- en alvleeskliercellen$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-context9.png$$,
   $$De onderzoekers vergeleken het mRNA van de organoïden met:
− het mRNA uit gifproducerende cellen van een gifklier;
− het mRNA uit cellen van de alvleesklier van dezelfde slangensoort. Na dit onderzoek trokken zij de conclusie dat de organoïden minigifkliertjes zijn.$$, 'inline'),
  ('e8bd97cb-d4c0-47b5-a528-347d78e32cd9', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', $$biobank met bevroren gifklier-organoïden; drie uitspraken over voordelen$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-context10.png$$,
   $$De onderzoekers willen een biobank oprichten met daarin bevroren gifklier-organoïden van vele soorten giftige slangen. Hieronder staan uitspraken over de voordelen van zo’n biobank.
1 Er hoeven dan minder gifslangen gemolken te worden.
2 Het is dan niet meer noodzakelijk om dieren te gebruiken voor het maken van een antiserum.
3 Een antiserum is dan direct beschikbaar.$$, 'inline'),
  ('28683bc6-de6a-4c94-9067-a78285c6bbe8', '3802324a-c683-42cc-93ea-1d7bc6b03007', $$inleiding: klimaatverandering en overstromingsbestendige planten (onderzoek Universiteit Utrecht)$$,
   $$biologie-vwo-2025-i-hoe-planten-overstroming-overleven-context1.png$$,
   $$Door klimaatverandering zullen rivieren vaker overstromen, waardoor oogsten verloren zullen gaan. Dit komt doordat de meeste landbouw- gewassen slecht bestand zijn tegen overstroming. Maar er zijn ook plantensoorten die beter bestand zijn tegen overstroming. Onderzoekers van de Universiteit Utrecht hebben onderzocht hoe dat komt.$$, 'inline'),
  ('5505c295-2ce5-475a-a150-8b1bf4917480', '3802324a-c683-42cc-93ea-1d7bc6b03007', $$wortels nemen normaal zuurstof op uit luchtholten in de bodem, bij overstroming gevuld met water$$,
   $$biologie-vwo-2025-i-hoe-planten-overstroming-overleven-context2.png$$,
   $$Wanneer landplanten in een natte bodem staan, levert dit vooral problemen op voor de wortels. Normaal nemen de wortels zuurstof op uit luchtholten in de bodem. Bij overstroming zijn deze holten echter gevuld met water.$$, 'inline'),
  ('d3386717-ef51-4f36-99f2-d04fe0598851', '3802324a-c683-42cc-93ea-1d7bc6b03007', $$overstroming vermindert de zuurstofopname door de wortels$$,
   $$biologie-vwo-2025-i-hoe-planten-overstroming-overleven-context3.png$$,
   $$Overstroming van de bodem leidt tot verminderde zuurstofopname door de wortels.$$, 'inline'),
  ('2433894a-7647-4877-86fc-000f997da76d', '3802324a-c683-42cc-93ea-1d7bc6b03007', $$zuurstoftekort in de wortels vermindert het transport van water naar de bladeren$$,
   $$biologie-vwo-2025-i-hoe-planten-overstroming-overleven-context4.png$$,
   $$Door het zuurstoftekort in de wortels zal het transport van water naar de bladeren afnemen.$$, 'inline'),
  ('52eba817-52e4-4a8b-98c9-c9eb6e5c64bf', '3802324a-c683-42cc-93ea-1d7bc6b03007', $$onderzoek naar het ethyleeneffect bij overstroming van de zandraket (afbeelding 1); ethyleen hoopt zich op onder water$$,
   $$biologie-vwo-2025-i-hoe-planten-overstroming-overleven-context5.png$$,
   $$De Utrechtse biologen deden onderzoek afbeelding 1 naar het effect dat het plantenhormoon ethyleen (etheen) heeft als planten door overstroming onder water komen te staan. In hun onderzoek aan de zandraket (Arabidopsis thaliana, afbeelding 1) toonden ze aan dat ethyleen de plant in overlevingsmodus brengt, waardoor de plant beter bestand wordt tegen zuurstofgebrek. Ethyleen is een stof die snel kan verdampen. Als planten volledig onder water staan, blijkt ethyleen zich op te hopen in de plant.$$, 'inline'),
  ('b863a4bb-ddd7-44ce-b196-9b9dfb45d71d', '3802324a-c683-42cc-93ea-1d7bc6b03007', $$moleculair mechanisme van de overlevingsmodus: ERF7, PRT6, PGB1 en stikstofoxide (afbeelding 2)$$,
   $$biologie-vwo-2025-i-hoe-planten-overstroming-overleven-context6.png$$,
   $$Bepaalde transcriptiefactoren, de zogenoemde ERF7’s (ethyleen-respons- factoren), sturen het proces aan dat een plant in de overlevingsmodus brengt. Zolang stikstofoxide (NO) en zuurstof aanwezig zijn, worden de ERF7’s afgebroken door het enzym PRT6. De onderzoekers ontdekten dat ethyleenophoping leidt tot een toename van de concentratie phytoglobine1 (PGB1) in de cellen van de groeipunten van de stengels en worteltoppen. PGB1 bindt stikstofoxide, waardoor de overstroomde plant in overlevingsmodus komt. De onderzoekers hebben een model opgesteld (afbeelding 2) van het moleculaire mechanisme dat de cel in overlevingsmodus brengt. In afbeelding 2 zijn de toename van de concentratie ethyleen en PGB1, en de toename van overlevingsprocessen bij volledige overstroming weergegeven met een pijltje ( ). De overlevingsmodusgenen zijn aangegeven met OMG. De afbeelding is niet compleet: bij drie stoffen en een proces in de cel staat een vakje met een nummer.
afbeelding 2$$, 'inline'),
  ('3ad89259-b40f-4799-bbfc-2fc9e9633371', '3802324a-c683-42cc-93ea-1d7bc6b03007', $$onderzoek naar het mechanisme met mutante zandraketplanten$$,
   $$biologie-vwo-2025-i-hoe-planten-overstroming-overleven-context7.png$$,
   $$De onderzoekers konden dit moleculaire mechanisme achterhalen door onderzoek te doen aan mutante zandraketplanten. Bij deze planten zijn verschillende delen van het proces om in de overlevingsmodus te komen, geblokkeerd.$$, 'inline'),
  ('9a5356ba-fb30-4c90-90f5-0e1b426dac5f', '3802324a-c683-42cc-93ea-1d7bc6b03007', $$typen zandraketplanten (ERF7-mutant, PRT6-mutant, wildtype) blootgesteld aan ethyleen en zuurstofgebrek; overleving van de worteltoppen (afbeelding 3)$$,
   $$biologie-vwo-2025-i-hoe-planten-overstroming-overleven-context8.png$$,
   $$De onderzoekers gebruikten de volgende typen zandraketplanten:
− planten met een mutatie waardoor een bepaalde ERF7 niet werkzaam is: de ERF7-mutanten
− planten met een mutatie waardoor het enzym PRT6 niet werkzaam is: de PRT6-mutanten
− wildtype-planten (zonder de mutaties) De onderzoekers plaatsten de planten in een ruimte waarin deze eerst werden blootgesteld aan lucht met ethyleen (nabootsing ethyleen- ophoping) of aan lucht zonder ethyleen (controle-voorbehandeling). Vervolgens stelden ze alle planten vier uur lang bloot aan lucht zonder zuurstof. Daarna werd de overleving van de worteltoppen van de planten bepaald (afbeelding 3).
afbeelding 3$$, 'inline'),
  ('7deb755e-6d83-4cc3-bda0-2392560c33b4', '3802324a-c683-42cc-93ea-1d7bc6b03007', $$drie uitspraken over de resultaten in afbeelding 3$$,
   $$biologie-vwo-2025-i-hoe-planten-overstroming-overleven-context9.png$$,
   $$Hieronder staan uitspraken over de resultaten in afbeelding 3.
1 De worteltoppen van het wildtype zijn beter bestand tegen zuurstofgebrek na een voorbehandeling met ethyleen.
2 Zowel met als zonder ethyleen-voorbehandeling is er bij ERF7- mutanten minder overleving van de worteltoppen dan bij wildtype- planten.
3 Het enzym PRT6 verhoogt de overleving bij volledige overstroming.$$, 'inline'),
  ('ca8e6cc1-635c-40e7-a24e-7e4a7af98b1e', '3802324a-c683-42cc-93ea-1d7bc6b03007', $$vier mogelijke genetische veranderingen om landbouwgewassen te beschermen tegen overstroming$$,
   $$biologie-vwo-2025-i-hoe-planten-overstroming-overleven-context10.png$$,
   $$De onderzoekers hopen de opgedane kennis te kunnen gebruiken om door middel van genetische modificatie landbouwgewassen te beschermen tegen overstromingen. Met genetische modificatie kunnen in landbouwgewassen de volgende veranderingen worden aangebracht:
1 het PGB1-gen knock-out maken
2 cisgene PGB1-genen toevoegen
3 genen voor ethyleenproductie knock-out maken
4 cisgene genen voor ethyleenproductie toevoegen$$, 'inline'),
  ('d2d856d9-f741-4cbb-b369-8a0e8cb83dd2', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$inleiding: nijlpaarden van Pablo Escobar aan hun lot overgelaten in Colombia$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context1.png$$,
   $$Toen de beruchte drugsbaron Pablo Escobar in 1993 was doodgeschoten, legde de Colombiaanse regering beslag op zijn landgoed en privédierentuin. De meeste dieren kregen een ander onderkomen, maar de nijlpaarden werden aan hun lot overgelaten, met grote gevolgen voor de aquatische ecosystemen in Colombia.$$, 'inline'),
  ('02497469-e628-4f2b-b4a7-b99297180702', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$nijlpaarden geïntroduceerd door Escobar; populatiegroei sinds 1980 met voorspelling (afbeelding 1, afbeelding 2)$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context2.png$$,
   $$Rond 1980 haalde Escobar vier nijlpaarden (Hippopotamus amphibius, afbeelding 1) uit Zuid-Afrika. Na 1993 nam de populatie op het landgoed sterk in grootte toe en verspreidde zich vanuit daar over het uitgestrekte merengebied langs de rivier de Magdalena. Nijlpaarden zijn semi-aquatische herbivoren: overdag verblijven ze in het water, ’s nachts verlaten ze het water om te gaan grazen.
afbeelding 1
In 2019 is de groei van de Colombiaanse nijlpaardenpopulatie in kaart gebracht en is er een voorspelling gemaakt van de groei van de populatie in de komende jaren. In afbeelding 2 geven gesloten bolletjes de waargenomen aantallen weer, en open bolletjes de voorspelde aantallen. In 2019 waren er tussen de 65 en 80 nijlpaarden.
afbeelding 2$$, 'inline'),
  ('8a710344-e6b0-4cb9-8b59-3a3d2a63dc2c', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$in Afrika veroorzaakt droogte hoge sterfte; in Colombia geen droogteperioden, regulatie door biotische factoren verwacht$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context3.png$$,
   $$In Afrika veroorzaken droge perioden een hoge sterfte onder nijlpaarden. In Colombia zijn er geen ernstige droogteperioden. De populatiegrootte zal daar waarschijnlijk op termijn gereguleerd worden door biotische factoren.$$, 'inline'),
  ('d6f19373-0d00-4cfe-9a8a-5e9b56dcc9e5', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$de nijlpaardenpopulatie in Colombia stamt af van slechts vier individuen$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context4.png$$,
   $$Doordat de nijlpaardenpopulatie in Colombia afstamt van slechts vier individuen, is de genenpool van deze populatie anders dan die van populaties in Afrika.$$, 'inline'),
  ('0c7c3099-7c46-4ef6-bb23-4c9219c64dc3', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$sommige wetenschappers denken dat de populatie zich tot een aparte soort zal ontwikkelen$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context5.png$$,
   $$Sommige wetenschappers denken dat de populatie nijlpaarden in Colombia zich zal ontwikkelen tot een aparte soort.$$, 'inline'),
  ('89955f68-8d48-4cd7-95ba-0d81d36cc39d', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$nijlpaarden als ecosystem engineers die successie kunnen tegengaan$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context6.png$$,
   $$Nijlpaarden worden ‘ecosystem engineers’ genoemd, omdat zij water- en landecosystemen ingrijpend beïnvloeden. Grote grazers zoals nijlpaarden kunnen successie in landecosystemen tegengaan doordat ze de vestiging en/of groei van pioniersoorten en climaxsoorten beïnvloeden.$$, 'inline'),
  ('757c9f21-fa70-4d42-a812-ee8e56cd95a5', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$isotopenonderzoek (13C/12C en 15N/14N) in meren met en zonder nijlpaarden; C3- en C4-planten; trofische niveaus (afbeelding 3)$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context7.png$$,
   $$Nijlpaarden eten op het land, maar poepen in het water. Ecologen wilden weten wat het effect hiervan is op ecosystemen in Colombia. Ze deden onderzoek in meren met nijlpaarden en in meren zonder nijlpaarden. De ecologen bepaalden daar van kleine organische moleculen:
− de verhouding tussen de koolstofisotopen 13C en 12C
− de verhouding tussen de stikstofisotopen 15N en 14N De verhouding 13C/12C verschilt tussen plantensoorten als gevolg van een verschil in fotosynthese. In gematigde streken zijn de meeste plantensoorten C3-planten. Het CO₂-fixerende enzym van C3-planten bindt voornamelijk CO₂ met de lichtere koolstofisotoop. C4-planten groeien alleen op land, en komen vaker voor in tropische gebieden zoals in Afrika en Colombia. Deze planten maken gebruik van een CO₂-fixerend enzym dat minder onderscheid maakt tussen de twee isotopen. Uit de verhouding 15N/14N van organische stoffen is af te leiden van welk trofisch niveau deze stoffen afkomstig zijn. In afbeelding 3 is de relatie tussen de verhouding 13C/12C en de verhouding 15N/14N weergegeven op drie trofische niveaus in twee voedselketens: een voedselketen gebaseerd op C3-planten en een voedselketen gebaseerd op C4-planten.
afbeelding 3$$, 'inline'),
  ('00d1a17e-784e-465a-8742-8d5150d3e977', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$het CO2-fixerende enzym van C3-planten bindt CO2 tot een C3-molecuul$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context8.png$$,
   $$Het CO₂-fixerende enzym van C3-planten bindt CO₂, waardoor een C3- molecuul gevormd wordt.$$, 'inline'),
  ('9bbbc995-e505-4a5c-8445-5ebdcca1b6cd', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$organismen hoger in de voedselketen bevatten relatief meer 15N$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context9.png$$,
   $$Organismen die hoger in de voedselketen staan, bevatten relatief meer 15N.$$, 'inline'),
  ('1c77bdc9-5e9f-458f-9709-c40b031b1a3e', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$metingen van 13C/12C en 15N/14N per meer in de Colombiaanse meren (afbeelding 4)$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context10.png$$,
   $$De resultaten van de bepalingen van de verhouding 13C/12C en de verhouding 15N/14N in de Colombiaanse meren zijn weergegeven in afbeelding 4. Elk bolletje geeft het gemiddelde aan van watermonsters die genomen zijn in een bepaald meer.
afbeelding 4$$, 'inline'),
  ('60b5a97e-f02c-4990-971e-668a1c358c66', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$toename van nijlpaarden verhoogt organische stoffen en verwacht eutrofiëring; zuurstofconcentratie gedurende 24 uur (afbeelding 5)$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context11.png$$,
   $$Met de toename van het aantal nijlpaarden neemt ook de concentratie organische stoffen in het water toe. De verwachting is dat op den duur eutrofiëring zal ontstaan. In een tweede onderzoek werd gedurende 24 uur de zuurstofconcentratie in het water gemeten in meren met nijlpaarden en in meren zonder nijlpaarden. In afbeelding 5 zijn de resultaten van twee meren met en twee meren zonder nijlpaarden weergegeven.
afbeelding 5$$, 'inline'),
  ('5d553fd0-28ce-42b6-bf65-361bbc575e5f', '809c72f3-ac2b-4f25-9b72-7aded685b2f1', $$nijlpaarden beïnvloeden de biodiversiteit; vier mogelijke gevolgen$$,
   $$biologie-vwo-2025-i-de-nijlpaarden-van-pablo-escobar-context12.png$$,
   $$Wetenschappers veronderstellen dat de nijlpaarden ook de biodiversiteit in het gebied zullen beïnvloeden. Hieronder staan gevolgen van de aanwezigheid van nijlpaarden.
1 Nijlpaarden concurreren met inheemse soorten zoals zeekoeien, rivierschildpadden en otters.
2 Nijlpaarden creëren meer verschillende habitats in de rivier.
3 Er zijn nijlpaardkadavers aanwezig.
4 Er treedt eutrofiëring op.$$, 'inline'),
  ('c367f354-ca5e-49c2-a80b-95c243a4832c', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$inleiding: team van John Wood onderzoekt families met afwijkende pijnbeleving (Marsili-syndroom)$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context1.png$$,
   $$Het team van neurobioloog John Wood onderzoekt families waarin een afwijkende pijnbeleving veel voorkomt. In 2018 beschreef Wood een erfelijke aandoening in de familie Marsili die ongevoelig maakt voor pijn. De aandoening kreeg de naam Marsili-syndroom. Het onderzoek van Wood kan bijdragen aan de ontwikkeling van nieuwe medicijnen voor het behandelen van chronische pijn.$$, 'inline'),
  ('58b9cd91-ee7c-475d-9add-ebde9307b11d', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$Letizia Marsili en familie ongevoelig voor pijn, hitte en kou door de Marsili-mutatie in het ZFHX2-gen; stamboom (afbeelding 1)$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context2.png$$,
   $$Letizia Marsili dacht dat ze gewoon stoer en sterk was: pijn, ijskou en bloedhete oppervlakken deden haar niets. Ook haar moeder Maria en vier andere leden van hun familie zijn nauwelijks gevoelig voor pijn, hitte en extreme kou. Wood en zijn team onderzochten Letizia en haar familie. Ze analyseerden het genoom van alle familieleden en vonden de oorzaak: een zeer zeldzame mutatie in het ZFHX2-gen, gelegen op chromosoom 14. Ze noemden deze mutatie de Marsili-mutatie. In afbeelding 1 is de stamboom van de familie van Letizia weergegeven.
afbeelding 1$$, 'inline'),
  ('9590ff48-cb6e-4b66-85df-1a3eca1fc4b1', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$Maria''s ouders voelden wel gewoon pijn; drie mogelijke periodes waarin de Marsili-mutatie kan zijn ontstaan$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context3.png$$,
   $$Maria’s ouders voelden wel gewoon pijn. Ergens voor of tijdens het leven van Maria is er een moment geweest dat de Marsili-mutatie in een cel is ontstaan. Hieronder staan drie perioden.
1 de periode waarin de geslachtscellen zijn gevormd waaruit Maria is ontstaan
2 de periode van de klievingsdelingen van de zygote waaruit Maria zich heeft ontwikkeld
3 de periode na Maria’s geboorte$$, 'inline'),
  ('979a69ce-9e59-4260-bec4-bbd0705a5afd', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$eigenschappen van Aδ-sensorische en C-sensorische neuronen bij stekende en zeurende pijn (tabel 1)$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context4.png$$,
   $$Na bijvoorbeeld een botbreuk ervaren mensen met een normale pijnbeleving eerst een stekende pijn en daarna een zeurende pijn. De pijnsignalen bij stekende pijn worden doorgegeven door Aδ-sensorische neuronen; bij zeurende pijn door C-sensorische neuronen. In tabel 1 zijn enkele eigenschappen gegeven van deze twee typen neuronen.
tabel 1
Aδ-sensorische C-sensorische neuronen neuronen type pijn stekende pijn zeurende pijn diameter uitlopers (µm) 1-5 0,2-2 geleidingssnelheid (m/s) 6-30 0,5-2 onderdeel P aanwezig afwezig$$, 'inline'),
  ('13ace1fc-5fa2-45fc-9e0a-891612db72ea', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$afwezigheid van onderdeel P mede bepalend voor trage geleidingssnelheid van C-sensorische neuronen$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context5.png$$,
   $$Behalve de kleine diameter van de uitlopers is ook de afwezigheid van onderdeel P bepalend voor de trage geleidingssnelheid van de C-sensorische neuronen bij zeurende pijn.$$, 'inline'),
  ('a8737adb-80af-4564-a51e-ed4b2001171a', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$Maria brak haar enkel, voelde een steek maar had er verder geen last van$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context6.png$$,
   $$Maria brak eens haar enkel bij een val. Ze voelde wel een steek, maar ze had er verder geen last van. Alleen vanwege de zwelling bezocht ze haar huisarts.$$, 'inline'),
  ('2813f896-9d77-4041-944f-e37997c01cd4', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$leden van de familie Marsili ongevoelig voor zeurende pijn door puntmutatie in het ZFHX2-gen (transcriptiefactor); genexpressie in C-sensorische neuronen$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context7.png$$,
   $$De leden van de familie Marsili zijn ongevoelig voor zeurende pijn doordat hun C-sensorische neuronen anders werken als gevolg van een puntmutatie in het ZFHX2-gen. Het ZFHX2-eiwit is een transcriptiefactor. Door de puntmutatie komen in de C-sensorische neuronen bepaalde genen die betrokken zijn bij de verwerking van pijnsignalen minder tot expressie.$$, 'inline'),
  ('29343228-ca49-4093-ad88-b20699b58fdf', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$doorsnede van het ruggenmerg met plaatsen P, Q en R van cellichamen van neuronen (afbeelding 2)$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context8.png$$,
   $$In afbeelding 2 is een doorsnede van het ruggenmerg weergegeven. De drie letters (P, Q en R) geven plaatsen aan waar zich cellichamen van neuronen bevinden.
afbeelding 2$$, 'inline'),
  ('82f4b7b2-a592-4779-87c9-7778e58d07e1', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$aminozuurvolgorde van het ZFHX2-eiwit rondom de Marsili-mutatie bij mens en diersoorten (tabel 2)$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context9.png$$,
   $$In tabel 2 is de aminozuurvolgorde van het ZFHX2-eiwit rondom de Marsili-mutatie bij de mens en bij verschillende diersoorten weergegeven.
tabel 2
mens met Marsili-mutatie QVWFQNTRAREKKGQFRSTP mens zonder de mutatie QVWFQNTRARERKGQFRSTP chimpansee QVWFQNTRARERKGQFRSTP hond QVWFQNTRARERKGQFRSTP huismuis QVWFQNTRARERKGQFRSTP$$, 'inline'),
  ('3af3966a-bc1e-4fd5-8ee5-e46bcc63c72c', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$de Marsili-mutatie bevindt zich in een deel van het gen waarin normaal geen genetische variatie aanwezig is$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context10.png$$,
   $$De Marsili-mutatie bevindt zich in een deel van het gen waarin normaal geen genetische variatie aanwezig is.$$, 'inline'),
  ('2d59f598-c297-4680-973c-d02eb3b39e77', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$onderzoeksteam concludeerde na muizenonderzoek dat de puntmutatie het afwijkende fenotype veroorzaakt$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context11.png$$,
   $$Het onderzoeksteam concludeerde na onderzoek aan huismuizen waarbij de Marsili-mutatie was aangebracht, dat de puntmutatie inderdaad het afwijkende fenotype veroorzaakt.$$, 'inline'),
  ('fc9c32df-cb2a-4337-98c3-3243330e41b5', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$John Wood vond families met IEM (extreme pijn bij warmte) en CIP (geen pijn); puntmutatie in het SCN9A-gen voor een Na+-kanaaltje in C-sensorische neuronen$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context12.png$$,
   $$John Wood heeft meer families opgespoord waarin een afwijkende pijnbeleving voorkomt. Hij vond families met leden die bij de geringste warmte extreme pijn ervaren; deze aandoening heet IEM (inherited erythromelalgia). Ook vond hij families met leden die juist helemaal geen pijn ervaren; deze aandoening wordt CIP genoemd (congenital insensitivity to pain). Beide aandoeningen worden veroorzaakt door een puntmutatie in het SCN9A-gen dat codeert voor een bepaald type Na⁺-kanaaltje dat aanwezig is in C-sensorische neuronen. Toen bekend was hoe een mutatie de pijn bij IEM veroorzaakt, kon naar een stof gezocht worden die het Na⁺-kanaaltje zo beïnvloedt dat het CIP-fenotype wordt nagebootst.$$, 'inline'),
  ('24538772-b72b-41d8-b708-aba0912b15fb', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$bij leden van één familie openen de Na+-kanaaltjes zich bij een kleinere stijging van de membraanpotentiaal dan normaal$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context13.png$$,
   $$Bij leden van één van de hierboven beschreven families openen de Na⁺-kanaaltjes in de C-sensorische neuronen zich bij een kleinere stijging van de membraanpotentiaal dan normaal.$$, 'inline'),
  ('615020e7-bd19-412a-ae2c-0ff09a971cf3', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$functieverlies (zoals bij CIP) en functiewinst (zoals bij IEM) van een mutatie; overerving wordt duidelijk bij heterozygote genotypen$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context14.png$$,
   $$Als een mutatie tot gevolg heeft dat een eiwit niet meer goed functioneert, heet dit functieverlies, zoals bij CIP. Er is sprake van functiewinst als door een mutatie een eiwit zodanig verandert dat het een nieuwe of versterkte werking heeft, zoals bij IEM. Bij heterozygote genotypen wordt het type overerving van deze mutaties duidelijk.$$, 'inline'),
  ('68e4713f-5d67-4244-a174-4aae101d9248', '77dea9d7-e2ec-4537-bea2-1fd1eca00551', $$een stof die Na+-kanaaltjes blokkeert zou pijnstillend zijn, maar de porie is gelijk aan die van andere Na+-kanaaltjes zoals in het hart$$,
   $$biologie-vwo-2025-i-onderzoek-naar-pijnbeleving-context15.png$$,
   $$Een stof die Na⁺-kanaaltjes in C-sensorische neuronen blokkeert, zou een pijnstillend medicijn zijn voor mensen met IEM en voor mensen met andere vormen van chronische pijn. Het is relatief eenvoudig om een stof te ontwerpen die de porie van het Na⁺-kanaaltje blokkeert. Het probleem is echter dat deze porie gelijk is aan de poriën van andere typen Na⁺-kanaaltjes, zoals de Na⁺-kanaaltjes in het hart.$$, 'inline'),
  ('813c10c7-8e52-4a07-80b0-9bbc039061d8', 'b3f40685-b831-4875-897a-bb5835b4aee9', $$inleiding: ziekenhuispersoneel met histamine-intoxicatie na bedorven tonijnsalade$$,
   $$biologie-vwo-2025-i-histamine-intoxicatie-context1.png$$,
   $$In 2018 meldden enkele personeelsleden van een ziekenhuis zich bij de spoedeisende hulp. Een alerte arts herkende de symptomen van histamine-intoxicatie. Waarschijnlijk hadden ze dit opgelopen door het eten van een bedorven tonijnsalade in het personeelsrestaurant.$$, 'inline'),
  ('3028a230-340c-401e-9e62-a4e05e77340f', 'b3f40685-b831-4875-897a-bb5835b4aee9', $$omzetting van histidine in histamine door het bacteriële enzym histidine-decarboxylase (afbeelding 1); histamine als mediator bij allergische reacties; symptomen$$,
   $$biologie-vwo-2025-i-histamine-intoxicatie-context2.png$$,
   $$Histamine-intoxicatie kan ontstaan bij mensen die bedorven voedsel hebben gegeten dat veel histamine bevat. Bacteriën, in bijvoorbeeld tonijnsalade, zetten de stof histidine om in histamine met behulp van het enzym histidine-decarboxylase (afbeelding 1). In het menselijk lichaam is histamine een mediator bij allergische reacties. De symptomen bij histamine-intoxicatie zijn benauwdheid, een rode huid, hartkloppingen en koorts.
afbeelding 1$$, 'inline'),
  ('66fc1de8-c10b-49be-8875-e18743685a5e', 'b3f40685-b831-4875-897a-bb5835b4aee9', $$de omzetting van histidine vindt vooral plaats boven de 4 °C$$,
   $$biologie-vwo-2025-i-histamine-intoxicatie-context3.png$$,
   $$De omzetting van histidine vindt vooral plaats boven de 4 °C.$$, 'inline'),
  ('3b28490b-e2d2-4f78-9d69-04d7418d4b43', 'b3f40685-b831-4875-897a-bb5835b4aee9', $$histamine-intoxicatie na bedorven voedsel met veel histidine, zoals vis en kaas$$,
   $$biologie-vwo-2025-i-histamine-intoxicatie-context4.png$$,
   $$Histamine-intoxicatie kan optreden na het eten van bedorven voedsel dat veel histidine bevat, zoals vis en kaas.$$, 'inline'),
  ('75b6a943-0845-4472-972c-9ea5caa851f7', 'b3f40685-b831-4875-897a-bb5835b4aee9', $$H1-receptor op gladde spiercellen in de bronchiolen; signaalcascade na histaminebinding leidt tot samentrekking (afbeelding 2)$$,
   $$biologie-vwo-2025-i-histamine-intoxicatie-context5.png$$,
   $$Op de membraan van gladde spiercellen in de bronchiolen is de histaminereceptor H1 (H1-receptor, afbeelding 2) aanwezig. Rechts in afbeelding 2 is de signaalcascade weergegeven die na binding van histamine aan de H1-receptor leidt tot samentrekking van de gladde spiercel.
afbeelding 2$$, 'inline'),
  ('50dce5d0-53c7-4475-8b5a-cd012336d03f', 'b3f40685-b831-4875-897a-bb5835b4aee9', $$moleculen die betrokken zijn bij de signaalcascade$$,
   $$biologie-vwo-2025-i-histamine-intoxicatie-context6.png$$,
   $$Bij signaalcascades spelen second messengers een belangrijke rol. Hieronder staan moleculen die zijn betrokken bij de signaalcascade.
1 H1-receptor
2 histamine
3 IP3
4 GDP$$, 'inline'),
  ('db28eb34-b2ce-471a-80d6-112f31369904', 'b3f40685-b831-4875-897a-bb5835b4aee9', $$benauwdheid door samentrekking van glad spierweefsel; toename van de ademhalingsfrequentie door stimulering van het ademcentrum$$,
   $$biologie-vwo-2025-i-histamine-intoxicatie-context7.png$$,
   $$De zieke personeelsleden hadden onder andere last van benauwdheid. De benauwdheid wordt veroorzaakt doordat histamine het glad spierweefsel in de bronchiolen laat samentrekken. Tijdens de benauwdheid neemt de ademhalingsfrequentie toe doordat het ademcentrum wordt gestimuleerd.$$, 'inline'),
  ('dfaed8aa-6b38-4031-80f8-66d131a35779', 'b3f40685-b831-4875-897a-bb5835b4aee9', $$H2-receptoren op gladde spiercellen rond de slagadertjes laten deze ontspannen; bloeddruk van de patiënt wordt bepaald$$,
   $$biologie-vwo-2025-i-histamine-intoxicatie-context8.png$$,
   $$In de gladde spiercellen rond de slagadertjes is een ander type histaminereceptoren aanwezig: de H2-receptoren. Binding van histamine aan H2-receptoren laat deze gladde spiercellen ontspannen. Bij histamine-intoxicatie wordt de bloeddruk van de patiënt bepaald.$$, 'inline'),
  ('a904505f-923b-4808-ab3f-b08ce554d36f', 'b3f40685-b831-4875-897a-bb5835b4aee9', $$koorts en een sterker doorbloede rode huid zijn tegenstrijdige symptomen$$,
   $$biologie-vwo-2025-i-histamine-intoxicatie-context9.png$$,
   $$Twee andere symptomen van histamine-intoxicatie zijn koorts en een sterker doorbloede en daardoor rode huid. Deze symptomen zijn tegenstrijdig.$$, 'inline'),
  ('01eb6ef8-3f0a-4e76-bbf2-d907cd45e2f1', 'b3f40685-b831-4875-897a-bb5835b4aee9', $$personeelsleden kregen clemastine-tabletten die de H1-receptoren blokkeren; farmacologische eigenschappen van clemastine (tabel)$$,
   $$biologie-vwo-2025-i-histamine-intoxicatie-context10.png$$,
   $$De personeelsleden met de histamine-intoxicatie kregen clemastine- tabletten. Clemastine blokkeert de H1-receptoren. In de tabel staan enkele farmacologische eigenschappen van dit medicijn.
maximale werking binnen 5 tot 7 uur na inname
werkingsduur tot 12 uur na inname
resorptie volledig
tijdsduur tot maximale 2 tot 4 uur na inname concentratie in het bloed opname uit de darmen vanaf 30 minuten na inname
afbraak in sterke mate in de lever$$, 'inline');

