   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-vraag4.png$$, $$1p 4 Verklaar dit op moleculair niveau.$$, array['fbf4145b-264f-4d6b-b2d8-24f17c75427c']::uuid[]),
  ('a2c5a961-b286-45f8-9f09-c101104cbadc', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', 5,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Zelforganisatie van cellen"}]'::jsonb,
   '["stamcellen", "celdifferentiatie", "delingsvermogen", "organoïden"]'::jsonb,
   $$Herkennen van een gegeven dat wijst op de aanwezigheid van stamcellen in een celkweek.$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-vraag5.png$$, $$1p 5 Licht toe welk gegeven uit de tekst in het kader erop wijst dat er stamcellen bij de losgemaakte cellen zaten.$$, array['f4c98945-8cd1-4bb3-9e8b-55e43dfcc363', '2068a2e9-518a-437d-b33d-a30d857a98f7']::uuid[]),
  ('30bff368-7628-416d-9c95-29629e4f86a0', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', 6,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Eiwitsynthese"}]'::jsonb,
   '["mRNA", "genexpressie", "celtype-identificatie", "vergelijkend onderzoek"]'::jsonb,
   $$Beschrijven van de resultaten van een vergelijking van mRNA-profielen tussen celtypen.$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-vraag6.png$$, $$2p 6 Beschrijf de resultaten van dit onderzoek.$$, array['a5ba4d7d-138b-417a-abbe-4c72694d277e']::uuid[]),
  ('841b82e5-026c-43cc-9daf-e1c9fedbaf0d', '870171bf-9a74-4034-ba9c-3b9109aa7b0b', 7,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Afweer van het organisme"}]'::jsonb,
   '["antiserum", "dierproeven", "biobank", "immunisatie"]'::jsonb,
   $$Beoordelen van uitspraken over de voordelen van een biobank met bevroren organoïden.$$,
   $$biologie-vwo-2025-i-slangengifklieren-uit-het-lab-vraag7.png$$, $$2p 7 Schrijf de nummers 1, 2 en 3 onder elkaar. Noteer erachter of de bijbehorende uitspraak juist of onjuist is.$$, array['e8bd97cb-d4c0-47b5-a528-347d78e32cd9']::uuid[]),
  ('769091b8-1572-4023-9e57-be8176123dc1', '3802324a-c683-42cc-93ea-1d7bc6b03007', 8,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["wet van Fick", "diffusie-oppervlak", "gaswisseling", "zuurstofopname", "wortels"]'::jsonb,
